IPv6 base header, 40 bytes (each row 32 bits)

  0       4              12                       20                31
 +-------+---------------+-----------------------------------------+
 |Ver=6  | Traffic Class |              Flow Label                 |
 +-------+---------------+-------------------+----------+----------+
 |        Payload Length |    Next Header    | Hop Limit|
 +-----------------------+-------------------+----------+
 |                  Source Address (128 bits)                      |
 |                                                                 |
 +-----------------------------------------------------------------+
 |                Destination Address (128 bits)                   |
 |                                                                 |
 +-----------------------------------------------------------------+

Extension chain example (TCP segment sent after a route header):
 [IPv6 NH=43] -> [Routing NH=6] -> [TCP header + data]

Hex: 60 00 00 00 00 14 06 40 + 32 address bytes
 version 6, TC 0, flow 0, payload length 20, next header 6 (TCP), hop limit 64

#include <stdint.h>
#include <stddef.h>
#include <arpa/inet.h>

struct ipv6_hdr {
    uint32_t ver_tc_flow;   /* 4 bits ver, 8 bits TC, 20 bits flow */
    uint16_t payload_len;
    uint8_t  next_hdr;
    uint8_t  hop_limit;
    uint8_t  src[16];
    uint8_t  dst[16];
};  /* sizeof == 40 */

/* Return the transport protocol, skipping HBH(0), routing(43),
   fragment(44) and destination options(60). */
int final_proto(const uint8_t *pkt, size_t len) {
    const struct ipv6_hdr *h = (const void *)pkt;
    uint8_t nh = h->next_hdr;
    size_t off = 40;
    for (int n = 0; n < 8; n++) {              /* bound the chain */
        if (nh == 0 || nh == 43 || nh == 60) {
            if (off + 2 > len) return -1;
            uint8_t next = pkt[off];
            off += 8 + 8 * (size_t)pkt[off + 1];
            nh = next;
        } else if (nh == 44) {                   /* fragment: 8 bytes */
            if (off + 8 > len) return -1;
            nh = pkt[off]; off += 8;
        } else return nh;                        /* 6, 17, 58, 59... */
    }
    return -1;
}
